// Feature configuration
Object.assign(mejs.MepDefaults, {
	/**
   * 弹幕按钮显示文字
	 * @type {?String}
	 */
  barrageText: null,
  /**
   * 弹幕列表
   * @type {?Array}
   */
  barrageList: [],
  /**
   * 弹幕文字颜色数组，用于随机选择数组中的颜色展示
   */
  barrageColors: [],
  /**
   * 插件目录，用于定位worker.js文件
   */
  barragePluginPath: '/'
});

Object.assign(MediaElementPlayer.prototype, {

	/**
	 * Feature constructor.
	 *
	 * Always has to be prefixed with `build` and the name that will be used in MepDefaults.features list
	 * @param {MediaElementPlayer} player
	 * @param {HTMLElement} controls
	 * @param {HTMLElement} layers
	 * @param {HTMLElement} media
	 */
	buildbarrage (player, controls, layers, media)  {
    let currentPosition = -1,
        duration = -1;
		const
      t = this,
			barrageText = mejs.Utils.isString(t.options.barrageText) ? t.options.barrageText : mejs.i18n.t('mejs.barrageText')||'弹幕',
      button = document.createElement('div'),
      canvasWrapper = document.createElement('div'),
      barrageList = t.options.barrageList instanceof Array ? t.options.barrageList : []
    ;
    var barrageOn = false,
        // worker = new Worker('mediaelement-plugins/src/barrage/worker.js'),
        worker = new Worker(`${t.options.barragePluginPath}worker.js`);

    // 初始化弹幕canvas
    canvasWrapper.className = `${t.options.classPrefix}overlay ${t.options.classPrefix}layer ${t.options.classPrefix}canvas-wrapper`
    canvasWrapper.innerHTML = `<canvas width=${t.width}px height=${t.height}px></canvas>`
    // console.log(player,media)
    layers.insertBefore(canvasWrapper, layers.firstChild);
    const canvas = layers.querySelector('canvas');
    const offscreen = canvas.transferControlToOffscreen();// 转移canvas控制权
    worker.postMessage({size:{width:t.width,height:t.height}});// 初始化宽高
    if(t.options.barrageColors instanceof Array && t.options.barrageColors.length > 0) {
      worker.postMessage({barrageColors: JSON.stringify(t.options.barrageColors)})
    }
    worker.postMessage({canvas:offscreen},[offscreen]);
    worker.onmessage = (e) => {
      console.log(e.data)
    }
    worker.onerror = (err) => {
      console.log(err)
    }

		button.className = `${t.options.classPrefix}button ${t.options.classPrefix}barrage-button ${t.options.classPrefix}barrage-on`;
		button.innerHTML = `<button type="button" aria-controls="${t.id}" title="${barrageText}" aria-label="${barrageText}" tabindex="0">${barrageText}</button>`;

		t.addControlElement(button, 'barrage');

    // // 进入全屏监听
    // t.getElement(t.container).addEventListener('enteredfullscreen',() => {
    //   console.log('11111:',player)
    //   offscreen.width = canvasWrapper.clientWidth;
    //   offscreen.heigh = canvasWrapper.clientHeight;
    //   t.resizeCanvasSize(t,player,canvasWrapper,worker)
    // })
    // // 退出全屏监听
    // t.getElement(t.container).addEventListener('exitedfullscreen',() => {
    //   console.log('22222',player)
    //   offscreen.width = canvasWrapper.clientWidth;
    //   offscreen.heigh = canvasWrapper.clientHeight;
    //   t.resizeCanvasSize(t,player,canvasWrapper,worker)
    // })
    media.addEventListener('durationchange', () => {
      duration = Math.floor(media.duration);
      console.log(`durationchange:${duration}`);
      if(worker) {
        worker.postMessage({barrageList:JSON.stringify(barrageList),duration:duration});
      }
    });
    media.addEventListener('timeupdate', mejs.Utils.throttle(() => {
      currentPosition = Math.floor(media.currentTime);
      // console.log(currentPosition)
      if(barrageOn) {
        worker && worker.postMessage({barrageTime: currentPosition})
      }
    },900));
    media.addEventListener('pause',() => {
      worker && worker.postMessage({pause:true})
    })
    media.addEventListener('play',() => {
      worker && worker.postMessage({play:true})
    })


		button.addEventListener('click', () => {
      if(barrageOn) {
        // 关闭弹幕
        canvasWrapper.style.visibility = 'hidden';
        // clearInterval(timer)
        worker && worker.postMessage({clear:true});
      }else {
        // 打开弹幕
        canvasWrapper.style.visibility = 'visible';
        // timer = setInterval(()=> {
        //   let list = t.options.barrageList instanceof Array ? t.options.barrageList : []
        //   worker.postMessage({list:JSON.stringify(list)});
        // },1000)
      }
      barrageOn = !barrageOn;
      console.log(`${barrageOn?'打开弹幕':'关闭弹幕'}`)
      button.className = `${t.options.classPrefix}button ${t.options.classPrefix}barrage-button ${t.options.classPrefix}${barrageOn?'barrage-off':'barrage-on'}`;
		});
  },
  // 重置弹幕canvas尺寸
  resizeCanvasSize: function(t,player,canvasWrapper,worker) {
    worker.postMessage({size:{width:canvasWrapper.clientWidth,height:canvasWrapper.clientHeight}})
  }
});

